P=[]
def pk(id, track, prio, title, owned, deps, deliv, oracle, accept, ifaces, coord, role='worker'):
    P.append(dict(id=id, sender='hw-'+id.lower(), role=role, track=track, priority=prio, title=title, owned_files=owned, depends_on=deps,
                  deliverable=deliv, host_test_oracle=oracle, acceptance_check=accept, interfaces=ifaces, coordinate_with=coord))

CLS_ORACLE = ("Unit tests call your class function directly on a struct n2a32_cpu whose mem->base is a 16 MiB calloc (guest addresses below 16 MiB), "
  "with encodings produced in run_tests.sh by `llvm-mc -triple=%s -mattr=+neon,+vfp4,+hwdiv,+hwdiv-arm,+fp-armv8 --show-encoding` from assembly text you write "
  "(never hand-typed hex), and expected register/flag/memory values written as literals worked out from the ARM ARM pseudocode. At least 6 cases per "
  "instruction form incl. flag edge cases (carry out, overflow, zero, negative), r15/sp operands where legal, and every addressing/shift variant. "
  "Every encoding of your class that llvm-mc can produce must either execute or return N2A32_UNDEF (never crash): a sweep test feeds 200000 random "
  "words of your encoding space under ASan/UBSan. When T01's differential harness exists (board), add your class's C kernels to it.")
def cls(id, prio, title, fn, files, what, triple, extra=''):
    pk(id,'V',prio,title, ['gpu/hwcodec/emu/%s' % f for f in files] + ['gpu/hwcodec/emu/test_%s/**' % id.lower()], ['include/n2a32.h (only this; no other package needed to start)'],
       ['%s implementing %s exactly under the contract in include/n2a32.h (the core has already checked the condition and set r[15]/next_pc/in_it; you return N2A32_OK or N2A32_UNDEF; branches only through n2a32_branch/n2a32_bx; memory only through n2a32_ld*/st*).' % (files[0], fn),
        what, 'test_%s/run_tests.sh and STATUS.md listing every mnemonic implemented and every encoding of the class deliberately left N2A32_UNDEF.' % id.lower()] + ([extra] if extra else []),
       CLS_ORACLE % triple, ['bash gpu/hwcodec/emu/test_%s/run_tests.sh -> N2TEST %s PASS n/n' % (id.lower(), id), 'the census of D01 (FACTS.md "instruction census") shows no mnemonic of your class used by the vendor libraries that you return UNDEF for'],
       'Implements: %s (include/n2a32.h).' % fn, ['hw-v02 (core: how it routes encodings to you; post your exact decode mask/match so its table is right)', 'hw-d01 (census)', 'hw-t01 (differential harness)', 'hw-iv'])

